describe('Password Confirmation Mismatch Error', () => {
  beforeEach(() => {
    cy.visit('/password-reset');
  });

  it('should display confirmation password mismatch error when passwords do not match', () => {
    // Intercept the API call to validate password
    cy.intercept('POST', '/api/validate-password').as('validatePassword');

    // Fill in the reset form with valid email
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Fill in the password fields
    cy.get('[data-testid="password-input"]').type('SecurePassword123');
    cy.get('[data-testid="confirm-password-input"]').type('IncorrectPassword123');

    // Submit the form
    cy.get('[data-testid="reset-password-form"]').submit();

    // Wait for the API validation response
    cy.wait('@validatePassword').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });

    // Verify error message is displayed
    cy.get('[data-testid="password-mismatch-error"]')
      .should('be.visible')
      .should('contain', 'Passwords do not match');

    // Verify error message is styled appropriately
    cy.get('[data-testid="password-mismatch-error"]')
      .should('have.class', 'error');

    // Verify form is still visible and user can retry
    cy.get('[data-testid="reset-password-form"]').should('be.visible');
  });

  it('should clear error message when passwords match', () => {
    // Intercept the API call to validate password
    cy.intercept('POST', '/api/validate-password').as('validatePassword');

    // Fill in the reset form with valid email
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Fill in the password fields with matching values
    cy.get('[data-testid="password-input"]').type('SecurePassword123');
    cy.get('[data-testid="confirm-password-input"]').type('SecurePassword123');

    // Submit the form
    cy.get('[data-testid="reset-password-form"]').submit();

    // Wait for the API validation response
    cy.wait('@validatePassword').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify error message is cleared
    cy.get('[data-testid="password-mismatch-error"]')
      .should('not.exist');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Password reset link sent to email');
  });
});
